#include "solvers/grayscott3d.hpp"
#include "solvers/run_options.hpp"
#include <navier/storage/dataset_store.hpp>
#include <numeric>
int main(int argc,char** argv){try{if(argc>7)throw std::invalid_argument("Usage: navier_grayscott3d [output] [NX] [NY] [NZ] [steps] [save-every]");const std::filesystem::path path=argc>1?argv[1]:"grayscott3d.data";const auto nx=argc>2?navier::examples::argument(argv[2]):32,ny=argc>3?navier::examples::argument(argv[3]):nx,nz=argc>4?navier::examples::argument(argv[4]):nx,steps=argc>5?navier::examples::argument(argv[5]):4000,interval=argc>6?navier::examples::argument(argv[6]):100;navier::examples::GrayScott3D solver({static_cast<std::size_t>(nx),static_cast<std::size_t>(ny),static_cast<std::size_t>(nz)});navier::storage::DatasetStore store(path,{.create=true,.metadata="{\"schema_version\":1,\"solver\":\"grayscott3d-fdm\",\"numerical_method\":\"forward Euler, 7-point Laplacian\",\"boundary\":\"periodic\",\"parameters\":{\"dt\":0.25,\"dx\":1,\"Du\":0.16,\"Dv\":0.08,\"feed\":0.04,\"kill\":0.06,\"initial\":\"central sphere with deterministic small perturbation\"}}"});const std::vector<std::uint64_t> shape{nx,ny,nz};const auto save=[&](std::uint64_t step){const std::array<navier::storage::FieldView,2> fields{{{{"species_u",navier::storage::ScalarType::float64,shape,"normalized concentration"},std::span<const double>(solver.species_u())},{{"species_v",navier::storage::ScalarType::float64,shape,"normalized concentration"},std::span<const double>(solver.species_v())}}};const auto& v=solver.species_v();const std::array<navier::storage::Metric,2> metrics{{{"mean_v",std::accumulate(v.begin(),v.end(),0.)/static_cast<double>(v.size()),"concentration"},{"max_v",*std::max_element(v.begin(),v.end()),"concentration"}}};store.save(step,static_cast<double>(step)*solver.dt(),fields,metrics);};save(0);for(std::uint64_t step=1;step<=steps;++step){solver.advance();if(step%interval==0||step==steps)save(step);}std::cout<<"GrayScott3D NAVIER02: "<<store.size()<<" analysis checkpoints\n";return 0;}catch(const std::exception& error){std::cerr<<"GrayScott3D: "<<error.what()<<'\n';return 1;}}
